1	//! `Vec<Item>` + `ModelRequest` → Anthropic Messages request body.
2	//!
3	//! Rules per the SMA-317 spec § "Wire translation". The translator
4	//! produces a `serde_json::Value` rather than typed structs to keep the
5	//! wire-snapshot tests readable.
6	//!
7	//! SMA-840: an assistant message can hold `ProviderData` parts of this crate.
8	//! They carry the `thinking` and `redacted_thinking` blocks of the response,
9	//! and the positions of each `text` block and each `tool_use` block. The
10	//! translator sends the blocks back and puts the blocks of each source
11	//! message in their response order. A history with no such part builds as
12	//! before.
13	//!
14	//! SMA-854: core joins the text blocks of a response into one text part.
15	//! When the text positions record their byte counts, the translator cuts the
16	//! joined text back into one `text` block for each position.
17	
18	use std::collections::{HashMap, VecDeque};
19	
20	use paigasus_helikon_core::{ContentPart, Item};
21	use serde_json::{json, Value};
22	
23	use crate::provider_data::{self, AnthropicData};
24	
25	/// Output of [`translate_messages`]: the top-level `system` field (string
26	/// or block-array form) and the `messages` array.
27	pub(crate) struct TranslatedMessages {
28	    pub(crate) system: Option<Value>,
29	    pub(crate) messages: Value,
30	    /// `true` when the last user message produced no message, no kept
31	    /// message or tool item follows it (dropped assistant items do not
32	    /// count), and the last sent message is an assistant one.
33	    pub(crate) trailing_message_dropped: bool,
34	}
35	
36	/// The sort key of a block inside its group.
37	#[derive(Debug, Clone, Copy)]
38	enum SortKey {
39	    /// `(index, 1)`, where `index` is the content-block index of the
40	    /// response. A `tool_use` block with no position has `(u64::MAX, 1)`.
41	    At(u64, u8),
42	    /// A text block of a group with no `text` position. The key becomes
43	    /// `(k, 0)`, where `k` is the smallest keyed `tool_use` index of the group
44	    /// in the same wire message, or `u64::MAX` when there is none.
45	    BeforeFirstToolUse,
46	}
47	
48	impl SortKey {
49	    fn resolve(self, first_tool_use: u64) -> (u64, u8) {
50	        match self {
51	            Self::At(index, rank) => (index, rank),
52	            Self::BeforeFirstToolUse => (first_tool_use, 0),
53	        }
54	    }
55	}
56	
57	/// The place of a block in the response order of its source message.
58	#[derive(Debug, Clone, Copy)]
59	struct Slot {
60	    /// The source message of the block. Keys of different groups are never
61	    /// compared.
62	    group: usize,
63	    key: SortKey,
64	    /// `true` when the source message has `tool_use` positions. Then its
65	    /// thinking blocks need a `tool_use` block of the group beside them that
66	    /// took one of these positions.
67	    needs_tool_use: bool,
68	}
69	
70	impl Slot {
71	    /// `true` when `block` lets the thinking blocks of this group stay: a
72	    /// `text` or `tool_use` block of the same group. When the group needs a
73	    /// `tool_use` block, only a `tool_use` block that took a position of the
74	    /// group counts. A call with no position did not come with the thinking
75	    /// block, so it does not count.
76	    fn is_kept_by(&self, block: &WireBlock) -> bool {
77	        let Some(slot) = block.slot.filter(|s| s.group == self.group) else {
78	            return false;
79	        };
80	        let took_position = matches!(slot.key, SortKey::At(index, _) if index != u64::MAX);
81	        !block.is_thinking() && (!self.needs_tool_use || (block.is_tool_use() && took_position))
82	    }
83	}
84	
85	/// One content block of a wire message. Only `value` reaches the JSON.
86	#[derive(Debug, Clone, Default)]
87	struct WireBlock {
88	    value: Value,
89	    /// `None` for a block that does not move in the final sort.
90	    slot: Option<Slot>,
91	    /// The text pieces of a splittable message (SMA-854), each with its own
92	    /// key. They are not blocks until [`expand_pieces`] runs, so the keep
93	    /// rule and the item decisions do not see them.
94	    pieces: Vec<(SortKey, String)>,
95	}
96	
97	impl WireBlock {
98	    fn plain(value: Value) -> Self {
99	        Self {
100	            value,
101	            slot: None,
102	            pieces: Vec::new(),
103	        }
104	    }
105	
106	    fn kind(&self) -> &str {
107	        self.value["type"].as_str().unwrap_or("")
108	    }
109	
110	    fn is_tool_use(&self) -> bool {
111	        self.kind() == "tool_use"
112	    }
113	
114	    fn is_thinking(&self) -> bool {
115	        matches!(self.kind(), "thinking" | "redacted_thinking")
116	    }
117	}
118	
119	/// One message of the `messages` array, before it becomes JSON.
120	#[derive(Debug, Clone)]
121	struct WireMessage {
122	    role: &'static str,
123	    content: Vec<WireBlock>,
124	}
125	
126	impl WireMessage {
127	    /// `true` when the message holds a block that lets the thinking blocks
128	    /// of the group of `slot` stay (see [`Slot::is_kept_by`]).
129	    fn keeps_thinking_of(&self, slot: Slot) -> bool {
130	        self.content.iter().any(|b| slot.is_kept_by(b))
131	    }
132	
133	    fn into_value(mut self) -> Value {
134	        drop_thinking_without_own_block(&mut self.content);
135	        expand_pieces(&mut self.content);
136	        sort_groups(&mut self.content);
137	        let content: Vec<Value> = self.content.into_iter().map(|b| b.value).collect();
138	        json!({"role": self.role, "content": content})
139	    }
140	}
141	
142	/// The Anthropic positions of one source message: an `AssistantMessage`
143	/// with at least one valid part of this crate, together with the
144	/// `Item::ToolCall` items that follow it before the next `AssistantMessage`
145	/// or the next user message with a part that is not a tool result.
146	#[derive(Debug, Clone)]
147	struct Source {
148	    group: usize,
149	    /// The wire message that holds the blocks of the `AssistantMessage`.
150	    /// `None` when it gave no block.
151	    wire: Option<usize>,
152	    /// The `tool_use` positions by call id, in the order of the parts.
153	    tool_positions: HashMap<String, VecDeque<u64>>,
154	    /// `true` when the message has at least one `tool_use` position.
155	    needs_tool_use: bool,
156	}
157	
158	impl Source {
159	    /// The key of the next `tool_use` block with `call_id`. Each position is
160	    /// used once, so a repeated id takes its positions in order.
161	    fn slot(&self, key: SortKey) -> Slot {
162	        Slot {
163	            group: self.group,
164	            key,
165	            needs_tool_use: self.needs_tool_use,
166	        }
167	    }
168	
169	    fn tool_key(&mut self, call_id: &str) -> SortKey {
170	        let index = self
171	            .tool_positions
172	            .get_mut(call_id)
173	            .and_then(VecDeque::pop_front);
174	        SortKey::At(index.unwrap_or(u64::MAX), 1)
175	    }
176	}
177	
178	/// The translator state before the item that made a tentative message.
179	#[derive(Debug)]
180	struct Saved {
181	    item: usize,
182	    messages_len: usize,
183	    system_len: usize,
184	    pending_tool_use: Vec<WireBlock>,
185	    pending_tool_results: Vec<Value>,
186	    last_item_dropped: bool,
187	    next_group: usize,
188	    source: Option<Source>,
189	}
190	
191	/// A wire assistant message that an item with only thinking blocks made.
192	///
193	/// It stays the last message until a message is pushed after it. If the
194	/// keep rule then fails for it (see [`Slot::is_kept_by`]), the translator
195	/// goes back to `saved`, drops the thinking blocks of the item, and
196	/// translates again from that item. At the end, the translator always goes
197	/// back, because the last assistant message sends no thinking block. The
198	/// item then counts as empty, as it did before SMA-840: no flush, no
199	/// message, and no change to the flag.
200	#[derive(Debug)]
201	struct Tentative {
202	    msg: usize,
203	    /// The slot of the thinking blocks of the item.
204	    slot: Slot,
205	    saved: Saved,
206	}
207	
208	/// The signal to go back to the saved state of the tentative message.
209	struct Rollback;
210	
211	#[derive(Debug, Default)]
212	struct Translator {
213	    system_text: String,
214	    messages: Vec<WireMessage>,
215	    pending_tool_use: Vec<WireBlock>,
216	    pending_tool_results: Vec<Value>,
217	    last_item_dropped: bool,
218	    next_group: usize,
219	    source: Option<Source>,
220	    tentative: Option<Tentative>,
221	    /// Tentative messages that a later push kept, in push order. A restore
222	    /// can make one of them the last message again. Then it is tentative
223	    /// again, because the end of the history can still drop its thinking.
224	    kept: Vec<Tentative>,
225	}
226	
227	/// Translate the conversation into Anthropic's request shape.
228	///
229	/// `system` is `None` when no `Item::System` has non-blank text. `messages`
230	/// is always an array. Text parts that are empty or whitespace only, and
231	/// messages left with no blocks, are dropped because the API rejects them.
232	///
233	/// A source message keeps its thinking blocks only when their wire message
234	/// also holds a `text` or `tool_use` block of the same source message. When
235	/// the source message has `tool_use` positions, that block must be one of
236	/// its own `tool_use` blocks. (A hand-off transcript or a trimmed history can
237	/// lose the calls of a response.) The last wire message, when it is an
238	/// assistant message, sends no thinking block. When a rule fails, the
239	/// thinking blocks are dropped, and the item builds as if it had no
240	/// Anthropic part. A thinking block must not go into a round that a
241	/// different response made.
242	///
243	/// - The thinking blocks of an item that joins an open round are removed in
244	///   the final pass when the rule fails. These blocks change no other
245	///   decision, so the result is the same as with no such blocks.
246	/// - An item with only thinking blocks that makes a new message can change
247	///   the flushes. When the rule fails for it, the translator goes back and
248	///   translates again from that item, with its thinking blocks dropped.
249	///   Decisions go in item order.
250	pub(crate) fn translate_messages(items: &[Item]) -> TranslatedMessages {
251	    let mut t = Translator::default();
252	    let mut drop_thinking = vec![false; items.len()];
253	    let mut i = 0;
254	    loop {
255	        let done = i == items.len();
256	        let step = if done {
257	            t.finish()
258	        } else {
259	            t.step(i, &items[i], drop_thinking[i])
260	        };
261	        match step {
262	            Ok(()) if done => break,
263	            Ok(()) => i += 1,
264	            Err(Rollback) => {
265	                let tentative = t
266	                    .tentative
267	                    .take()
268	                    .expect("a rollback needs a tentative message");
269	                i = tentative.saved.item;
270	                // Each rollback drops one more item, so the loop ends.
271	                drop_thinking[i] = true;
272	                t.restore(tentative.saved);
273	            }
274	        }
275	    }
276	    t.into_output()
277	}
278	
279	impl Translator {
280	    fn step(&mut self, i: usize, item: &Item, drop_thinking: bool) -> Result<(), Rollback> {
281	        match item {
282	            Item::System { content } => {
283	                self.flush_pending_assistant()?;
284	                self.flush_pending_user()?;
285	                if !self.system_text.is_empty() {
286	                    self.system_text.push('\n');
287	                }
288	                self.system_text.push_str(&text_of(content));
289	            }
290	            Item::UserMessage { content } => {
291	                // A user message with a part that is not a tool result ends
292	                // the source message (the SMA-827 Gemini rule).
293	                if content
294	                    .iter()
295	                    .any(|p| !matches!(p, ContentPart::ToolResult { .. }))
296	                {
297	                    self.source = None;
298	                }
299	                self.flush_pending_assistant()?;
300	                // Pending tool_results go at the front of this user turn.
301	                let mut blocks: Vec<Value> = std::mem::take(&mut self.pending_tool_results);
302	                blocks.extend(user_blocks(content));
303	                self.last_item_dropped = blocks.is_empty();
304	                if !blocks.is_empty() {
305	                    let blocks = blocks.into_iter().map(WireBlock::plain).collect();
306	                    self.push_message("user", blocks)?;
307	                }
308	            }
309	            Item::AssistantMessage { content, agent: _ } => {
310	                let (mut blocks, source) = assistant_blocks(content, self.next_group);
311	                if drop_thinking {
312	                    blocks.retain(|b| !b.is_thinking());
313	                }
314	                // An assistant item with no blocks acts as if it were absent:
315	                // it flushes nothing (so an open tool round stays whole) and
316	                // leaves the flag as it is (a drop of the user turn before
317	                // it still counts). A kept assistant message ends the drop.
318	                //
319	                // A message of only tool uses and thinking blocks is the
320	                // nested form of `Item::ToolCall`, or the accumulator form of
321	                // a thinking round (SMA-834, SMA-840). Inside an open round it
322	                // joins that round, as a call does. A flush would put a user
323	                // turn that lacks some results right after the open assistant
324	                // turn. On this path the last message is an assistant message
325	                // (`round_is_answered` is `true` for an empty trailing
326	                // assistant run). `pending_tool_use` is empty, because each
327	                // `ToolResult` flushes it. So the append keeps the order.
328	                // Setting `last_item_dropped` here is for symmetry. The flag
329	                // is already `false`, because a `ToolResult` came after any
330	                // dropped user message.
331	                let only_tool_uses =
332	                    !blocks.is_empty() && blocks.iter().all(|b| b.is_tool_use() || b.is_thinking());
333	                let joins = only_tool_uses
334	                    && !self.pending_tool_results.is_empty()
335	                    && !round_is_answered(&self.messages, &self.pending_tool_results);
336	                let thinking_only = !blocks.is_empty() && blocks.iter().all(WireBlock::is_thinking);
337	                let saved = (thinking_only && !joins).then(|| self.save(i));
338	                if source.is_some() {
339	                    self.next_group += 1;
340	                }
341	                self.source = source;
342	                if joins {
343	                    self.last_item_dropped = false;
344	                    let target = self.tool_use_target();
345	                    if let Some(source) = &mut self.source {
346	                        source.wire = Some(target);
347	                    }
348	                    self.push_tool_uses(blocks);
349	                } else if !blocks.is_empty() {
350	                    self.flush_pending_assistant()?;
351	                    self.flush_pending_user()?;
352	                    self.last_item_dropped = false;
353	                    let msg = self.messages.len();
354	                    self.push_message("assistant", blocks)?;
355	                    if let Some(source) = &mut self.source {
356	                        source.wire = Some(msg);
357	                    }
358	                    if let Some(saved) = saved {
359	                        // `push_message` cleared any older tentative message.
360	                        debug_assert!(self.tentative.is_none());
361	                        let slot = self
362	                            .source
363	                            .as_ref()
364	                            .map(|s| s.slot(SortKey::At(0, 1)))
365	                            .expect("a thinking block comes from a valid part");
366	                        self.tentative = Some(Tentative { msg, slot, saved });
367	                    }
368	                }
369	            }
370	            Item::ToolCall {
371	                call_id,
372	                name,
373	                args,
374	            } => {
375	                self.last_item_dropped = false;
376	                // A new tool_use follows any results already seen. Close
377	                // that user turn first only when the last assistant round is
378	                // fully answered; otherwise the call joins that round.
379	                if round_is_answered(&self.messages, &self.pending_tool_results) {
380	                    self.flush_pending_user()?;
381	                }
382	                // The call keeps its key only in the wire message that holds
383	                // the blocks of its source message.
384	                let target = self.tool_use_target();
385	                let slot = self.source.as_mut().and_then(|source| {
386	                    let key = source.tool_key(call_id);
387	                    (source.wire == Some(target)).then(|| source.slot(key))
388	                });
389	                let value = json!({
390	                    "type": "tool_use",
391	                    "id": call_id,
392	                    "name": name,
393	                    "input": args,
394	                });
395	                self.push_tool_uses(vec![WireBlock {
396	                    value,
397	                    slot,
398	                    pieces: Vec::new(),
399	                }]);
400	            }
401	            Item::ToolResult { call_id, content } => {
402	                self.last_item_dropped = false;
403	                self.flush_pending_assistant()?;
404	                self.pending_tool_results.push(json!({
405	                    "type": "tool_result",
406	                    "tool_use_id": call_id,
407	                    "content": text_of(content),
408	                }));
409	            }
410	            _ => {
411	                tracing::warn!(
412	                    target: "paigasus::anthropic::translate",
413	                    "unknown Item variant; skipping",
414	                );
415	            }
416	        }
417	        Ok(())
418	    }
419	
420	    fn finish(&mut self) -> Result<(), Rollback> {
421	        self.flush_pending_assistant()?;
422	        self.flush_pending_user()?;
423	        // A tentative message at the end is the last assistant message. It
424	        // sends no thinking block, so the item counts as empty.
425	        match self.tentative {
426	            Some(_) => Err(Rollback),
427	            None => Ok(()),
428	        }
429	    }
430	
431	    /// Push a message. A tentative message before it is then complete: keep
432	    /// it when the keep rule holds for it, else go back.
433	    fn push_message(
434	        &mut self,
435	        role: &'static str,
436	        content: Vec<WireBlock>,
437	    ) -> Result<(), Rollback> {
438	        if let Some(t) = &self.tentative {
439	            debug_assert_eq!(
440	                t.msg + 1,
441	                self.messages.len(),
442	                "a tentative message is last"
443	            );
444	            if !self.messages[t.msg].keeps_thinking_of(t.slot) {
445	                return Err(Rollback);
446	            }
447	            self.kept.extend(self.tentative.take());
448	        }
449	        self.messages.push(WireMessage { role, content });
450	        Ok(())
451	    }
452	
453	    fn flush_pending_assistant(&mut self) -> Result<(), Rollback> {
454	        if self.pending_tool_use.is_empty() {
455	            return Ok(());
456	        }
457	        let content = std::mem::take(&mut self.pending_tool_use);
458	        self.push_message("assistant", content)
459	    }
460	
461	    fn flush_pending_user(&mut self) -> Result<(), Rollback> {
462	        if self.pending_tool_results.is_empty() {
463	            return Ok(());
464	        }
465	        let content = std::mem::take(&mut self.pending_tool_results)
466	            .into_iter()
467	            .map(WireBlock::plain)
468	            .collect();
469	        self.push_message("user", content)
470	    }
471	
472	    /// The index of the wire message that `push_tool_uses` adds to now.
473	    fn tool_use_target(&self) -> usize {
474	        match self.messages.last() {
475	            Some(m) if m.role == "assistant" => self.messages.len() - 1,
476	            // Queued blocks flush into the next message.
477	            _ => self.messages.len(),
478	        }
479	    }
480	
481	    /// Add `tool_use` blocks to the open assistant turn. When the last
482	    /// message is an assistant message, extend it. Otherwise queue them.
483	    fn push_tool_uses(&mut self, blocks: Vec<WireBlock>) {
484	        match self.messages.last_mut() {
485	            Some(last) if last.role == "assistant" => last.content.extend(blocks),
486	            _ => self.pending_tool_use.extend(blocks),
487	        }
488	    }
489	
490	    fn save(&self, item: usize) -> Saved {
491	        Saved {
492	            item,
493	            messages_len: self.messages.len(),
494	            system_len: self.system_text.len(),
495	            pending_tool_use: self.pending_tool_use.clone(),
496	            pending_tool_results: self.pending_tool_results.clone(),
497	            last_item_dropped: self.last_item_dropped,
498	            next_group: self.next_group,
499	            source: self.source.clone(),
500	        }
501	    }
502	
503	    /// Go back to `saved`. The messages before `saved.messages_len` did not
504	    /// change after the save: only the last message gets new blocks, and the
505	    /// tentative message and all later ones are at or after that length.
506	    ///
507	    /// `saved` does not hold a tentative message. A tentative message that
508	    /// was active when `saved` was taken was resolved by a later push in the
509	    /// same step. That push is a flush of the pending blocks or the push of
510	    /// the new tentative message. If the older message was not kept, that
511	    /// push rolled back to the older save, and this `saved` was discarded.
512	    /// If it was kept, it is in `kept`. It is the last message at
513	    /// `saved.messages_len`, so the restore makes it tentative again. Its
514	    /// own save is still correct, because no message before its own saved
515	    /// length changed.
516	    fn restore(&mut self, saved: Saved) {
517	        self.messages.truncate(saved.messages_len);
518	        self.system_text.truncate(saved.system_len);
519	        self.pending_tool_use = saved.pending_tool_use;
520	        self.pending_tool_results = saved.pending_tool_results;
521	        self.last_item_dropped = saved.last_item_dropped;
522	        self.next_group = saved.next_group;
523	        self.source = saved.source;
524	        let len = self.messages.len();
525	        self.kept.retain(|t| t.msg < len);
526	        self.tentative = match self.kept.last() {
527	            Some(t) if t.msg + 1 == len => self.kept.pop(),
528	            _ => None,
529	        };
530	    }
531	
532	    fn into_output(self) -> TranslatedMessages {
533	        let trailing_message_dropped =
534	            self.last_item_dropped && self.messages.last().is_some_and(|m| m.role == "assistant");
535	        let system = if self.system_text.trim().is_empty() {
536	            None
537	        } else {
538	            Some(Value::String(self.system_text))
539	        };
540	        let mut messages = self.messages;
541	        // A caller prefill or a continuation ends with an assistant message.
542	        // That message sends no thinking block, and its blocks keep the
543	        // order of the parts.
544	        if let Some(last) = messages.last_mut().filter(|m| m.role == "assistant") {
545	            last.content.retain(|b| !b.is_thinking());
546	            for block in &mut last.content {
547	                block.slot = None;
548	            }
549	        }
550	        let messages = messages.into_iter().map(WireMessage::into_value).collect();
551	        TranslatedMessages {
552	            system,
553	            messages: Value::Array(messages),
554	            trailing_message_dropped,
555	        }
556	    }
557	}
558	
559	/// Remove each thinking block that the keep rule does not keep in this
560	/// message (see [`Slot::is_kept_by`]).
561	fn drop_thinking_without_own_block(content: &mut Vec<WireBlock>) {
562	    let keep: Vec<bool> = content
563	        .iter()
564	        .map(|b| match b.slot {
565	            Some(slot) if b.is_thinking() => content.iter().any(|o| slot.is_kept_by(o)),
566	            _ => true,
567	        })
568	        .collect();
569	    // A source that loses its thinking also loses its sort slots. Its blocks
570	    // then keep the plain order, as without Anthropic metadata.
571	    let lost: Vec<usize> = content
572	        .iter()
573	        .zip(&keep)
574	        .filter(|(b, kept)| !**kept && b.is_thinking())
575	        .filter_map(|(b, _)| b.slot.map(|s| s.group))
576	        .collect();
577	    let mut keep = keep.into_iter();
578	    content.retain(|_| keep.next().unwrap_or(true));
579	    for block in content.iter_mut() {
580	        if block.slot.is_some_and(|s| lost.contains(&s.group)) {
581	            block.slot = None;
582	        }
583	    }
584	}
