586	/// Turn the text pieces into `text` blocks (SMA-854).
587	///
588	/// Only a block that still has its slot expands. A text block is replaced by
589	/// its pieces. A thinking block stays, and its pieces go right after it. A
590	/// block with no slot lost its thinking, or is in the last assistant message,
591	/// so its pieces are dropped and a text block stays one joined block.
592	fn expand_pieces(content: &mut Vec<WireBlock>) {
593	    if content.iter().all(|b| b.pieces.is_empty()) {
594	        return;
595	    }
596	    let mut out = Vec::with_capacity(content.len());
597	    for mut block in content.drain(..) {
598	        let pieces = std::mem::take(&mut block.pieces);
599	        let Some(slot) = block.slot.filter(|_| !pieces.is_empty()) else {
600	            out.push(block);
601	            continue;
602	        };
603	        if block.is_thinking() {
604	            out.push(block);
605	        }
606	        out.extend(pieces.into_iter().map(|(key, text)| WireBlock {
607	            value: json!({"type": "text", "text": text}),
608	            slot: Some(Slot { key, ..slot }),
609	            pieces: Vec::new(),
610	        }));
611	    }
612	    *content = out;
613	}
