615	/// Put the blocks of each group back in response order.
616	///
617	/// For each group, take the positions its blocks have in the message, sort
618	/// those blocks by key (stable), and write them back into the same
619	/// positions. Blocks of other groups and blocks with no slot do not move.
620	fn sort_groups(content: &mut [WireBlock]) {
621	    let mut groups: Vec<usize> = Vec::new();
622	    for slot in content.iter().filter_map(|b| b.slot) {
623	        if !groups.contains(&slot.group) {
624	            groups.push(slot.group);
625	        }
626	    }
627	    for group in groups {
628	        let at: Vec<usize> = content
629	            .iter()
630	            .enumerate()
631	            .filter(|(_, b)| b.slot.is_some_and(|s| s.group == group))
632	            .map(|(i, _)| i)
633	            .collect();
634	        let first_tool_use = at
635	            .iter()
636	            .filter(|&&i| content[i].is_tool_use())
