642	            .unwrap_or(u64::MAX);
643	        let mut taken: Vec<WireBlock> = at
644	            .iter()
645	            .map(|&i| std::mem::take(&mut content[i]))
646	            .collect();
647	        taken.sort_by_key(|b| b.slot.map(|s| s.key.resolve(first_tool_use)));
648	        for (i, block) in at.into_iter().zip(taken) {
649	            content[i] = block;
650	        }
